"""Generate ``results/README.md`` from the result tables, so quoted numbers never drift."""

from __future__ import annotations

from collections.abc import Callable, Sequence
from pathlib import Path
from typing import TYPE_CHECKING, SupportsFloat

import numpy as np
import pandas as pd

from climate_risk.credit.transition import SECTORS
from climate_risk.term_structure.projection import quantile_label

if TYPE_CHECKING:
    from climate_risk.pipeline import Results

HEADER = (
    "# Results\n\n"
    "_Generated by `climate-risk run` — do not edit by hand._ Credit inputs: **{mode}** mode. "
    "All tables are also available as CSV in [`tables/`](tables/) and every chart in "
    "[`figures/`](figures/).\n"
)


def _number(value: SupportsFloat, digits: int) -> str:
    """Fixed-point text without a negative zero ("-0.0" → "0.0")."""
    return f"{round(float(value), digits) + 0.0:.{digits}f}"


def markdown_table(frame: pd.DataFrame, fmt: Callable[[object], str] | None = None) -> str:
    """Minimal GitHub-flavoured markdown table (index included)."""
    cell = fmt or (lambda v: _number(v, 2) if isinstance(v, int | float | np.floating) else str(v))
    names = [n for n in frame.index.names if n is not None]
    header = [" · ".join(map(str, names)), *map(str, frame.columns)]
    lines = ["| " + " | ".join(header) + " |", "|" + "---|" * len(header)]
    for idx, row in frame.iterrows():
        label = " · ".join(map(str, idx)) if isinstance(idx, tuple) else str(idx)
        lines.append("| " + " | ".join([label, *(cell(v) for v in row)]) + " |")
    return "\n".join(lines)


def _section(title: str, body: str, note: str = "") -> str:
    return f"\n## {title}\n\n{note + chr(10) + chr(10) if note else ''}{body}\n"


def _yields(res: Results, years: Sequence[int]) -> str:
    proj = res.tables["yield_projection_10y"]
    names = list(
        dict.fromkeys([*res.config.scenarios.narratives, *res.config.scenarios.policy_family])
    )
    quantiles = res.config.simulation.quantiles
    low, high = quantile_label(quantiles[0]), quantile_label(quantiles[-1])
    rows = {}
    for name in names:
        series = proj.loc[name]
        rows[name] = {
            str(y): f"{series.loc[y, 'mean']:.2f} [{series.loc[y, low]:.2f}, "
            f"{series.loc[y, high]:.2f}]"
            for y in years
        }
    table = pd.DataFrame(rows).T
    table.index.name = "scenario"
    return markdown_table(table)


def _backtest(res: Results) -> str:
    rel = res.tables["backtest_relative_rmse"]
    horizons = [h for h in (12, 24, 60) if h in rel.index.get_level_values("horizon")]
    rows = {}
    for model in ("DNS AR(1)", "DNS VAR(1)", "Shifting-endpoint VAR(1)"):
        for maturity in (2.0, 10.0):
            if maturity in rel.columns:
                rows[f"{model} · {maturity:g}y"] = {
                    f"{h}m": rel.loc[(model, h), maturity] for h in horizons
                }
    table = pd.DataFrame(rows).T
    table.index.name = "model · maturity"
    return markdown_table(table, lambda v: f"{v:.3f}")


def _credit(res: Results) -> str:
    cal = res.tables["credit_calibration"]
    cols = {
        "issuers": "issuers",
        "cds_PX1_bp": "CDS 1y (bp)",
        "cds_PX5_bp": "CDS 5y (bp)",
        "cds_PX10_bp": "CDS 10y (bp)",
        "pd_5y": "PD 5y (Q)",
        "pd_10y": "PD 10y (Q)",
        "merton_sigma": "σ_A",
        "merton_leverage": "D/V",
    }
    table = cal[list(cols)].rename(columns=cols)
    table["issuers"] = table["issuers"].astype(int).astype(str)

    def fmt(v: object) -> str:
        if isinstance(v, str):
            return v
        value = float(v)  # type: ignore[arg-type]
        return _number(value, 3) if value < 1 else _number(value, 1)

    return markdown_table(table, fmt)


def _spreads(res: Results) -> str:
    spreads = res.tables["climate_spreads"]
    chi = res.config.credit.chi
    central = spreads[np.isclose(spreads["chi"], chi)]
    table = central.pivot_table(
        index=["policy", "sector"], columns="tenor", values="climate_spread_bp"
    )[[5.0, 10.0, 30.0]]
    table.columns = [f"{c:g}y" for c in table.columns]
    lo, hi = min(res.config.credit.chi_sensitivity), max(res.config.credit.chi_sensitivity)
    ten = spreads[np.isclose(spreads["tenor"], 10.0)].pivot_table(
        index=["policy", "sector"], columns="chi", values="climate_spread_bp"
    )
    table[f"10y, χ={lo:g}–{hi:g}"] = [
        f"{_number(a, 0)} to {_number(b, 0)}" for a, b in zip(ten[lo], ten[hi], strict=True)
    ]
    table.index.names = ["policy", "sector"]
    return markdown_table(table, lambda v: v if isinstance(v, str) else _number(v, 1))  # type: ignore[arg-type]


def _bonds(res: Results) -> str:
    impact = res.tables["bond_value_impact"]
    sel = impact[np.isclose(impact["maturity"], 10.0)].set_index(["policy", "sector"])
    table = 100 * sel[["rate", "credit", "interaction", "total"]]
    table.columns = ["risk-free (%)", "credit (%)", "interaction (%)", "total (%)"]
    table.insert(0, "Δ risk-free (bp)", sel["riskfree_shift_bp"])
    return markdown_table(table, lambda v: _number(v, 2))  # type: ignore[arg-type]


def _portfolio(res: Results) -> str:
    risk = res.tables["portfolio_risk"]
    sel = risk[risk["measure"] == "Physical"].pivot_table(
        index="scenario", columns="copula", values="es"
    )
    table = 100 * sel
    table.columns = [f"ES {100 * res.config.portfolio.alpha:.0f}% · {c}" for c in table.columns]
    return markdown_table(table, lambda v: _number(v, 1))  # type: ignore[arg-type]


def _sensitivity(res: Results) -> str:
    credit = res.tables["credit_sensitivity"]
    table = credit.pivot_table(
        index="variant", columns="sector", values="climate_spread_bp", sort=False
    )
    table = table[list(SECTORS)]
    table.columns = [f"climate spread · {c} (bp)" for c in table.columns]
    shift = credit.groupby("variant", sort=False)["riskfree_shift_bp"].first()
    value = credit[credit["sector"] == "Oil & gas"].set_index("variant")["bond_value_change"]
    table.insert(0, "Δ risk-free 10y (bp)", shift)
    table["oil & gas bond (%)"] = 100 * value
    table.index.name = "variant"
    return markdown_table(table, lambda v: _number(v, 1))  # type: ignore[arg-type]


def _rates_sensitivity(res: Results) -> str:
    rates = res.tables["rates_sensitivity"]
    policies = [p for _, p in res.config.scenarios.transitions if p.endswith("1.9")]
    sel = rates[rates["scenario"].isin(policies)]
    table = sel.pivot_table(
        index="variant", columns="scenario", values="repricing_10y_bp", sort=False
    )[policies]
    table.columns = [f"{c} (bp)" for c in table.columns]
    table.index.name = "variant"
    return markdown_table(table, lambda v: _number(v, 1))  # type: ignore[arg-type]


def build(res: Results) -> str:
    rates = res.tables["rates_summary"]["value"]
    modes = res.tables["cycle_var_modes"].loc["Shifting-endpoint VAR(1) (cycle)"]
    jump = res.rates.jump_off
    parts = [HEADER.format(mode=res.credit.mode.upper())]
    parts.append(
        _section(
            "Term structure",
            f"- Decay λ̂ = {rates['lambda_per_year']:.3f}/yr (curvature peak "
            f"{rates['curvature_peak_years']:.1f}y), {int(rates['months'])} monthly curves.\n"
            f"- Cycle VAR half-lives: "
            f"{', '.join(f'{h:.0f}' for h in modes['half_life_months'])} months.\n"
            f"- Jump-off {jump.month}: r* = {jump.rstar:.2f}%, π* = {jump.inflation:.2f}%, "
            f"i* = {jump.istar:.2f}%.\n\n"
            "**Expected 10-year zero yield, % (mean "
            f"[{100 * res.config.simulation.quantiles[0]:g}%, "
            f"{100 * res.config.simulation.quantiles[-1]:g}%])**\n\n"
            + _yields(res, (2030, 2050, 2100)),
        )
    )
    if "backtest_relative_rmse" in res.tables:
        parts.append(
            _section("Out-of-sample forecasts (RMSE relative to random walk)", _backtest(res))
        )
    parts.append(_section("Baseline credit calibration (sector medians)", _credit(res)))
    parts.append(
        _section(
            "Climate spreads if the transition is priced today (bp)",
            _spreads(res),
            f"Central elasticity χ = {res.config.credit.chi:g}; tenors beyond 10y use flat-hazard "
            "extrapolation.",
        )
    )
    parts.append(_section("Repricing of 10-year zero-coupon bonds at revelation", _bonds(res)))
    baseline, policy = res.config.scenarios.headline
    parts.append(
        _section(
            f"Sensitivity of the headline result ({policy} vs {baseline}, 10-year bonds)",
            _sensitivity(res),
            "One assumption changed at a time; the convergence year applies to both the "
            "carbon-price catch-up (rates) and the output-shock catch-up (credit).",
        )
    )
    parts.append(
        _section(
            "Repricing of the 10-year Treasury yield at revelation, by assumption",
            _rates_sensitivity(res),
        )
    )
    parts.append(
        _section(
            f"Portfolio Expected Shortfall over {res.config.portfolio.horizon} years "
            "(physical measure, % of notional)",
            _portfolio(res),
        )
    )
    return "".join(parts)


def write(res: Results, path: Path) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(build(res), encoding="utf-8")
    return path
